/* Opening names for a position, from the Lichess chess-openings tables.

   openings.json is generated by tools/chess-assets/gen-openings.mjs from
   https://github.com/lichess-org/chess-openings (CC0, fetched 2026-08-30).
   Each entry is [epd, eco, name] where epd is the first four FEN fields, so a
   transposition into a known position is recognized however it was reached.

   The file is about 450 KB, so it is fetched once, on demand, and only for the
   analysis board. Everything here fails quietly: if the fetch does not land,
   the caller simply gets null and the page carries on. */

import { fetchJson } from './json-fetch.js';

let table = null;          // Map<epd, {eco, name}>
let loading = null;        // in-flight fetch, so a burst of lookups shares one

const epdOf = fen => String(fen).split(' ').slice(0, 4).join(' ');

export function loadOpenings(url = './chess-assets/openings.json') {
  if (table) return Promise.resolve(table);
  if (loading) return loading;
  loading = fetchJson(url, { maxBytes: 2 * 1024 * 1024 })
    .then(data => {
      if (!data) throw new Error('openings did not load');
      const map = new Map();
      const rows = data && Array.isArray(data.entries) ? data.entries : [];
      for (const row of rows) {
        if (!Array.isArray(row) || row.length < 3) continue;
        const [epd, eco, name] = row;
        if (typeof epd !== 'string' || typeof eco !== 'string' || typeof name !== 'string') continue;
        if (!/^[1-8pnbrqkPNBRQK/]+ [wb] (-|[KQkq]{1,4}) (-|[a-h][36])$/.test(epd)) continue;
        if (!/^[A-E]\d\d$/.test(eco) || name.length > 120) continue;
        map.set(epd, { eco, name });
      }
      table = map;
      return table;
    })
    .catch(() => { loading = null; return null; });
  return loading;
}

/* The name of one position, or null. Synchronous: the table must be loaded. */
export function openingOf(fen) {
  if (!table) return null;
  return table.get(epdOf(fen)) || null;
}

/* The name of the line a game is in: the last named position along its move
   list, plus how many plies have been played since theory ran out. `fens` is
   the position after each move, oldest first, including the starting one. */
export function openingOfLine(fens) {
  if (!table || !Array.isArray(fens)) return null;
  let best = null, at = -1;
  for (let i = 0; i < fens.length; i++) {
    const hit = table.get(epdOf(fens[i]));
    if (hit) { best = hit; at = i; }
  }
  return best ? { ...best, ply: at, since: fens.length - 1 - at } : null;
}
export const openingsReady = () => !!table;
export { epdOf };
